/****** Object:  StoredProcedure [dbo].[CreateUserSession]    Script Date: 23/04/2026 3:56:15 p. m. ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[CreateUserSession]
    @UserId NVARCHAR(255),
    @DeviceId NVARCHAR(100),
    @SessionToken NVARCHAR(255),
    @IssuedAt DATETIME2,
    @IpAddress NVARCHAR(45),
    @IsActive BIT = 1,
    @IsBlocked BIT = 0
AS
BEGIN
    INSERT INTO UserSessions (
        user_id,
        device_id,
        session_token,
        issued_at,
        is_active,
        ip_address,
        is_blocked,
        created_at,
        updated_at
        )
    VALUES (
        @UserId,
        @DeviceId,
        @SessionToken,
        @IssuedAt,
        @IsActive,
        @IpAddress,
        @IsBlocked,
        SWITCHOFFSET(SYSDATETIMEOFFSET(), '-05:00'),
        SWITCHOFFSET(SYSDATETIMEOFFSET(), '-05:00')
    );
END;

GO
/****** Object:  StoredProcedure [dbo].[GetActiveSessionByUserId]    Script Date: 23/04/2026 3:56:15 p. m. ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[GetActiveSessionByUserId]
    @UserId NVARCHAR(255),
    @DeviceId NVARCHAR(255)
AS
BEGIN
    SELECT TOP 1
        u.user_id,
        u.email,
        u.display_name,
        us.device_id,
        us.session_token,
        us.issued_at,
        us.ip_address,
        us.is_active,
        us.is_blocked,
        DATEDIFF(SECOND, us.created_at, us.updated_at) AS diff_seconds
    FROM [dbo].[UserSessions] us
    INNER JOIN [dbo].[Users] u ON us.user_id = u.user_id
    WHERE us.user_id = @UserId AND us.device_id = @DeviceId
    ORDER BY us.issued_at DESC;
END;
GO
