/****** Object:  StoredProcedure [dbo].[GetUserById]    Script Date: 23/04/2026 3:56:15 p. m. ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetUserById]
    @user_id NVARCHAR(255)
AS
BEGIN
    SELECT 
        u.user_id,
        u.email,
        u.display_name,
        u.enable,
        u.department,
        u.phone,
        u.role,
        u.created_at,
        u.type_person,
        u.type_dni,
        u.identity_document,  -- Changed from COALESCE(u.dni, u.identity_document)
        u.reference,
        u.reference2,
        u.personal_email,
        p.id,
        p.product_name,
        p.contract_duration,
        p.duration_unit,
        p.expiration,
        p.country,
        p.state,
        p.city,
        p.amount_cop,
        p.enable AS product_enable
    FROM Users u
    LEFT JOIN Products p ON u.user_id = p.user_id
    WHERE u.user_id = @user_id;
END;
