SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[InvalidateAllUserSessions] 
      @UserId NVARCHAR(255) 
  AS BEGIN
      UPDATE UserSessions
      SET is_active = 0,
          updated_at = SWITCHOFFSET(SYSDATETIMEOFFSET(), '-05:00')
      WHERE user_id = @UserId
        AND is_active = 1;
  END;
GO
