CREATE PROCEDURE [dbo].[InvalidateUserSessions]
    @UserId NVARCHAR(255),
    @DeviceId NVARCHAR(100)
AS
BEGIN
    UPDATE UserSessions
    SET is_active = 0,
        updated_at = SWITCHOFFSET(SYSDATETIMEOFFSET(), '-05:00')
    WHERE user_id = @UserId AND device_id = @DeviceId AND is_active = 1;
END;

