/****** Object:  StoredProcedure [dbo].[UpsertProduct]    Script Date: 23/04/2026 3:56:15 p. m. ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[UpsertProduct]
    @Id INT,
    @UserId NVARCHAR(100),
    @ProductName NVARCHAR(100),
    @ContractDuration INT,
    @DurationUnit NVARCHAR(20),
    @Expiration DATETIME,
    @Country NVARCHAR(20),
    @State NVARCHAR(2000),
    @City NVARCHAR(2000),
    @Enable BIT,
    @AmountCop DECIMAL(10,2)
AS
BEGIN
    IF EXISTS (
        SELECT 1 FROM Products
        WHERE user_id = @UserId AND id = @Id
    )
    BEGIN
        UPDATE Products
        SET
            product_name = @ProductName,
            contract_duration = @ContractDuration,
            duration_unit = @DurationUnit,
            expiration = @Expiration,
            country = @Country,
            [state] = @State,
            city = @City,
            [enable] = @Enable,
            amount_cop = @AmountCop
        WHERE user_id = @UserId AND id = @Id
    END
    ELSE
    BEGIN
        INSERT INTO Products (
            user_id, product_name, contract_duration, duration_unit, expiration, country, [state], city, amount_cop
        ) VALUES (
            @UserId, @ProductName, @ContractDuration, @DurationUnit, @Expiration, @Country, @State, @City, @AmountCop
        )
    END
END

